/**
 * 3D jar models built from the client's product photography.
 *
 * Each texture in public/images/jars is the jar body from the product photo, "unwrapped"
 * into a 360° cylindrical label: the photographed front (~190°) is sine-unwrapped to undo
 * the camera's foreshortening, and the back is filled with grain sampled from the same
 * photo's ground spice. Generated by scripts/unwrap-jar-labels.cjs.
 */

export type JarSlug = 'biryani-masala';

export interface JarModel {
  slug: JarSlug;
  name: string;
  /** Body height ÷ body radius, measured from the photo. */
  aspect: number;
  /** Average colour of the ground spice (top surface / glow). */
  powder: string;
}

export const jarModels: Record<JarSlug, JarModel> = {
  'biryani-masala': { slug: 'biryani-masala', name: 'Biryani Masala', aspect: 1.738, powder: '#a55c24' },
};

export const jarTexture = (slug: JarSlug, size: 1024 | 1536 = 1024) => `/images/jars/${slug}-${size}.webp`;

/** The jar used by the loading screen. Preloaded from index.html. */
export const loaderJar = jarModels['biryani-masala'];
